package memba_dao_candidature_v3

// memba_dao_candidature — Membership application realm for MembaDAO.
//
// Provides a transparent, on-chain candidature flow:
//   1. Applicant calls Apply(bio, skills) with a deposit
//   2. Application is stored on-chain (visible to all)
//   3. Any DAO member can create an AddMember proposal referencing the application
//   4. DAO votes on the proposal (66% threshold)
//   5. If approved, member is added via basedao's built-in AddMember handler
//
// Anti-spam:
//   - Required deposit (10 GNOT default, 10x increase on re-application)
//   - Max bio/skills length (5000 chars)
//   - Cannot apply if already a member
//
// Security:
//   - Deposits are held in the realm until withdrawn by applicant
//   - MarkApproved/MarkRejected restricted to admin allowlist (owner-managed)
//   - Owner can add/remove admins and transfer ownership
//   - Admin cap of 20 addresses to limit blast radius

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// ── Constants ────────────────────────────────────────────────

const (
	MinDeposit      int64 = 10_000_000 // 10 GNOT in ugnot
	DepositMultiply int64 = 10         // 10x on re-application
	MaxApplyCount         = 10         // Maximum re-applications (prevents int64 overflow at 10^17)
	MaxBioLen             = 5000
	MaxSkillsLen          = 5000
	MaxAdmins             = 20   // Maximum number of admin addresses
	MaxApplications       = 1000 // Global cap to prevent unbounded state growth
)

// ── Types ────────────────────────────────────────────────────

type Application struct {
	Address    address
	Bio        string
	Skills     string
	Deposit    int64
	Status     string // "pending", "approved", "rejected", "withdrawn"
	AppliedAt  int64  // block height
	ApplyCount int    // number of times applied (for deposit scaling)
}

// ── State ────────────────────────────────────────────────────

var (
	applications *avl.Tree // address -> *Application
	applyCount   *avl.Tree // address -> int (total apply count, persists across withdrawals)
	admins       *avl.Tree // address -> bool (authorized callers for MarkApproved/MarkRejected)
	paused       bool
	// Owner is set at package load time via OriginCaller() — this captures the
	// deployer address (samcrew-core-test1 multisig on testnet).
	owner = unsafe.OriginCaller()
)

func init() {
	applications = avl.NewTree()
	applyCount = avl.NewTree()
	admins = avl.NewTree()
	admins.Set(owner.String(), true)
}

// ── Emergency Pause ────────────────────────────────────────

func assertNotPaused() {
	if paused {
		panic("realm is paused — emergency maintenance")
	}
}

func Pause(cur realm) {
	assertCallerIsOwner()
	paused = true
}

func Unpause(cur realm) {
	assertCallerIsOwner()
	paused = false
}

func IsPaused() bool { return paused }

// ── Public API ───────────────────────────────────────────────

// Apply submits a membership application with a deposit.
// The caller must send at least MinDeposit * (10 ^ previousAttempts) ugnot.
func Apply(cur realm, bio string, skills string) {
	assertNotPaused()

	// P0 fund-guard: a payable entrypoint MUST be a direct user call. unsafe.OriginSend()
	// reports the tx-level `--send`, which is credited to the DIRECT message target realm
	// — not to an inner realm reached via a cross-call. Without this guard an attacker
	// routes Apply through their own intermediary realm (coins land there), records a
	// phantom Deposit this realm never received, then drains real pooled deposits via
	// Withdraw. Requiring a direct user call forces this realm to be the message target,
	// the one condition under which the OriginSend coins are guaranteed to be in its account.
	if !unsafe.PreviousRealm().IsUserCall() {
		panic("Apply must be a direct user call")
	}

	caller := unsafe.PreviousRealm().Address()

	// Validate inputs
	if len(bio) == 0 {
		panic("bio cannot be empty")
	}
	if len(bio) > MaxBioLen {
		panic(ufmt.Sprintf("bio too long: %d/%d chars", len(bio), MaxBioLen))
	}
	if len(skills) > MaxSkillsLen {
		panic(ufmt.Sprintf("skills too long: %d/%d chars", len(skills), MaxSkillsLen))
	}

	// Check for existing pending application
	isNewApplicant := true
	if val, exists := applications.Get(caller.String()); exists {
		isNewApplicant = false
		app := val.(*Application)
		if app.Status == "pending" {
			panic("you already have a pending application")
		}
	}
	// Enforce global cap only for truly new applicants (not re-applications)
	if isNewApplicant && applications.Size() >= MaxApplications {
		panic(ufmt.Sprintf("application limit reached: %d", MaxApplications))
	}

	// Calculate required deposit (10x per previous attempt, capped to prevent overflow)
	count := getApplyCount(caller)
	if count >= MaxApplyCount {
		panic(ufmt.Sprintf("maximum re-application limit reached (%d)", MaxApplyCount))
	}
	required := MinDeposit
	for i := 0; i < count; i++ {
		required *= DepositMultiply
	}

	// Verify deposit (accumulate to handle multi-denom entries defensively)
	sent := unsafe.OriginSend()
	sentAmount := int64(0)
	for _, coin := range sent {
		if coin.Denom == "ugnot" {
			sentAmount += coin.Amount
		}
	}
	if sentAmount < required {
		panic(ufmt.Sprintf("insufficient deposit: sent %d, required %d ugnot", sentAmount, required))
	}

	// Store application
	app := &Application{
		Address:    caller,
		Bio:        bio,
		Skills:     skills,
		Deposit:    sentAmount,
		Status:     "pending",
		AppliedAt:  runtime.ChainHeight(),
		ApplyCount: count + 1,
	}
	applications.Set(caller.String(), app)
	applyCount.Set(caller.String(), count+1)

	chain.Emit("ApplicationSubmitted",
		"applicant", caller.String(),
		"deposit", strconv.FormatInt(sentAmount, 10),
		"attempt", strconv.Itoa(count+1),
	)
}

// Withdraw allows an applicant to withdraw their pending application and reclaim deposit.
func Withdraw(cur realm) {
	caller := unsafe.PreviousRealm().Address()

	val, exists := applications.Get(caller.String())
	if !exists {
		panic("no application found")
	}
	app := val.(*Application)
	if app.Status != "pending" {
		panic("can only withdraw pending applications")
	}

	// STATE-BEFORE-SEND: update status and zero deposit before coin transfer
	app.Status = "withdrawn"
	deposit := app.Deposit
	app.Deposit = 0
	applications.Set(caller.String(), app)

	// Return deposit
	if deposit > 0 {
		b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		b.SendCoins(unsafe.CurrentRealm().Address(), caller, chain.Coins{chain.NewCoin("ugnot", deposit)})
	}
}

// MarkApproved is called by authorized admins to mark an application as approved.
// Only addresses in the admin allowlist can call this function.
func MarkApproved(cur realm, applicant address) {
	assertCallerIsAdmin()

	val, exists := applications.Get(applicant.String())
	if !exists {
		panic("no application found for " + applicant.String())
	}
	app := val.(*Application)
	if app.Status != "pending" {
		panic("application is not pending")
	}
	// STATE-BEFORE-SEND: update status before returning deposit
	app.Status = "approved"
	deposit := app.Deposit
	app.Deposit = 0
	applications.Set(applicant.String(), app)

	// Return deposit on approval (same as rejection)
	if deposit > 0 {
		b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		b.SendCoins(unsafe.CurrentRealm().Address(), applicant, chain.Coins{chain.NewCoin("ugnot", deposit)})
	}

	chain.Emit("ApplicationApproved",
		"applicant", applicant.String(),
		"approvedBy", unsafe.PreviousRealm().Address().String(),
	)
}

// MarkRejected is called by authorized admins to mark an application as rejected.
// Only addresses in the admin allowlist can call this function.
func MarkRejected(cur realm, applicant address) {
	assertCallerIsAdmin()

	val, exists := applications.Get(applicant.String())
	if !exists {
		panic("no application found for " + applicant.String())
	}
	app := val.(*Application)
	if app.Status != "pending" {
		panic("application is not pending")
	}
	// STATE-BEFORE-SEND: update status and zero deposit before coin transfer
	app.Status = "rejected"
	deposit := app.Deposit
	app.Deposit = 0
	applications.Set(applicant.String(), app)

	// Return deposit on rejection
	if deposit > 0 {
		b := banker.NewBanker(banker.BankerTypeRealmSend, cur)
		b.SendCoins(unsafe.CurrentRealm().Address(), applicant, chain.Coins{chain.NewCoin("ugnot", deposit)})
	}

	chain.Emit("ApplicationRejected",
		"applicant", applicant.String(),
		"rejectedBy", unsafe.PreviousRealm().Address().String(),
	)
}

// ── Admin Management ────────────────────────────────────────

// AddAdmin adds an address to the admin allowlist. Only the owner can call this.
func AddAdmin(cur realm, addr address) {
	assertCallerIsOwner()
	assertValidAddress(addr)
	if admins.Size() >= MaxAdmins {
		panic(ufmt.Sprintf("admin limit reached: %d/%d", admins.Size(), MaxAdmins))
	}
	admins.Set(addr.String(), true)
}

// RemoveAdmin removes an address from the admin allowlist. Only the owner can call this.
func RemoveAdmin(cur realm, addr address) {
	assertCallerIsOwner()
	if addr == owner {
		panic("cannot remove owner from admins")
	}
	if _, exists := admins.Get(addr.String()); !exists {
		panic("address is not an admin: " + addr.String())
	}
	admins.Remove(addr.String())
}

// TransferOwnership transfers realm ownership to a new address.
// The new owner is also added as admin. The old owner remains as admin
// (the new owner can remove them via RemoveAdmin if desired).
// Only the current owner can call this.
func TransferOwnership(cur realm, newOwner address) {
	assertCallerIsOwner()
	assertValidAddress(newOwner)
	if newOwner == owner {
		panic("new owner is the same as current owner")
	}
	admins.Set(newOwner.String(), true)
	owner = newOwner
}

// IsAdmin returns whether an address is in the admin allowlist.
func IsAdmin(addr address) bool {
	_, exists := admins.Get(addr.String())
	return exists
}

// GetOwner returns the current realm owner address.
func GetOwner() address {
	return owner
}

// ListAdmins returns all admin addresses as a comma-separated string.
func ListAdmins() string {
	var addrs []string
	admins.Iterate("", "", func(key string, value any) bool {
		addrs = append(addrs, key)
		return false
	})
	return strings.Join(addrs, ",")
}

// ── Queries ──────────────────────────────────────────────────

// GetApplication returns the application for a given address (or empty if none).
func GetApplication(addr string) string {
	val, exists := applications.Get(addr)
	if !exists {
		return ""
	}
	app := val.(*Application)
	return ufmt.Sprintf("%s|%s|%s|%d|%s|%d|%d",
		app.Address, app.Bio, app.Skills, app.Deposit, app.Status, app.AppliedAt, app.ApplyCount)
}

// ── Render ───────────────────────────────────────────────────

func Render(path string) string {
	if path == "" {
		return renderHome()
	}
	if strings.HasPrefix(path, "application/") {
		addr := strings.TrimPrefix(path, "application/")
		return renderApplication(addr)
	}
	return "# 404\nPage not found: " + path
}

func renderHome() string {
	var sb strings.Builder
	sb.WriteString("# MembaDAO Candidature\n\n")
	sb.WriteString("Apply to join the Memba community.\n\n")

	// Count by status
	pending, approved, rejected := 0, 0, 0
	applications.Iterate("", "", func(key string, value any) bool {
		app := value.(*Application)
		switch app.Status {
		case "pending":
			pending++
		case "approved":
			approved++
		case "rejected":
			rejected++
		}
		return false
	})

	sb.WriteString(ufmt.Sprintf("**Stats:** %d pending | %d approved | %d rejected\n", pending, approved, rejected))
	sb.WriteString(ufmt.Sprintf("**Owner:** %s | **Admins:** %d\n\n", owner, admins.Size()))

	// List pending applications
	if pending > 0 {
		sb.WriteString("## Pending Applications\n\n")
		applications.Iterate("", "", func(key string, value any) bool {
			app := value.(*Application)
			if app.Status == "pending" {
				sb.WriteString(ufmt.Sprintf("- [%s](:application/%s) — deposit: %s GNOT — block %d\n",
					app.Address, app.Address, formatGNOT(app.Deposit), app.AppliedAt))
			}
			return false
		})
	}

	return sb.String()
}

func renderApplication(addr string) string {
	val, exists := applications.Get(addr)
	if !exists {
		return "# Application Not Found\nNo application for " + addr
	}
	app := val.(*Application)

	var sb strings.Builder
	sb.WriteString(ufmt.Sprintf("# Application: %s\n\n", app.Address))
	sb.WriteString(ufmt.Sprintf("**Status:** %s\n", app.Status))
	sb.WriteString(ufmt.Sprintf("**Deposit:** %s GNOT\n", formatGNOT(app.Deposit)))
	sb.WriteString(ufmt.Sprintf("**Applied at block:** %d\n", app.AppliedAt))
	sb.WriteString(ufmt.Sprintf("**Attempt #:** %d\n\n", app.ApplyCount))
	sb.WriteString("## Bio\n\n")
	sb.WriteString(sanitizeForRender(app.Bio) + "\n\n")
	sb.WriteString("## Skills\n\n")
	sb.WriteString(sanitizeForRender(app.Skills) + "\n")

	return sb.String()
}

// ── Helpers ──────────────────────────────────────────────────

// sanitizeForRender strips markdown-sensitive characters to prevent injection.
func sanitizeForRender(s string) string {
	var out strings.Builder
	for _, c := range s {
		switch c {
		case '[', ']', '(', ')', '#', '*', '`', '!', '<', '>', '|', '\\', '_', '~', '\n', '\r', '\t':
			continue
		default:
			out.WriteRune(c)
		}
	}
	return out.String()
}

func assertCallerIsAdmin() {
	caller := unsafe.PreviousRealm().Address()
	if _, exists := admins.Get(caller.String()); !exists {
		panic("unauthorized: caller " + caller.String() + " is not an admin")
	}
}

func assertCallerIsOwner() {
	caller := unsafe.PreviousRealm().Address()
	if caller != owner {
		panic("unauthorized: caller " + caller.String() + " is not the owner")
	}
}

func assertValidAddress(addr address) {
	if addr == "" {
		panic("address cannot be empty")
	}
}

func getApplyCount(addr address) int {
	val, exists := applyCount.Get(addr.String())
	if !exists {
		return 0
	}
	return val.(int)
}

func formatGNOT(ugnot int64) string {
	gnot := ugnot / 1_000_000
	remainder := ugnot % 1_000_000
	if remainder == 0 {
		return strconv.FormatInt(gnot, 10)
	}
	return ufmt.Sprintf("%d.%06d", gnot, remainder)
}

package escrow_v3

// Milestone-based Escrow — On-chain freelance service contracts for Memba.
//
// Flow: CreateContract → FundMilestone → CompleteMilestone → ReleaseFunds
// Disputes: RaiseDispute → admin resolves (or auto-resolves after timeout)
// Timeouts: ClaimRefund (auto-refund if milestone not completed after N blocks)
//           ClaimDisputeTimeout (auto-release to freelancer if admin doesn't act)
//
// Security:
//   - STATE-BEFORE-SEND: All state updates happen before SendCoins calls
//   - FeeRecipient validated in init()
//   - Self-hire prevention: freelancer != client
//   - Input validation: title/description length, milestone amounts > 0
//   - Auto-refund: prevents permanent fund locking
//   - Dispute timeout: prevents permanent dispute locking
//
// Render() contract:
//   Home — Render(""):
//     # Escrow Contracts
//     | ID | Title | Client | Freelancer | Status | Total |
//
//   Detail — Render("contract/ID"):
//     # Title
//     **Client:** g1...
//     **Freelancer:** g1...
//     **Status:** active
//     ## Milestones
//     - **Milestone Title** — 1000000 ugnot [funded]

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// ── Constants ────────────────────────────────────────────────

const (
	AdminAddress    = "g1x7k4628w93a7wzdhqc06atzx0v50rnshweuxu0" // samcrew-core-test1 multisig
	FeeRecipient    = "g1x7k4628w93a7wzdhqc06atzx0v50rnshweuxu0" // Samourai Coop multisig
	PlatformFeePct  = 2  // 2%
	CancelFeePct    = 5  // 5% cancellation fee
	AutoRefundBlks  = int64(864000)  // ~30 days at 3s/block
	AutoResolveBlks = int64(806400)  // ~28 days at 3s/block
	MaxTitleLen        = 200
	MaxDescLen         = 5000
	MaxMilestones      = 20
	MaxContracts       = 500
	MinMilestoneAmount = int64(1000) // 0.001 GNOT — prevents fee evasion via truncation
)

// ── Types ────────────────────────────────────────────────────

type ContractStatus string

const (
	StatusActive    ContractStatus = "active"
	StatusCompleted ContractStatus = "completed"
	StatusDisputed  ContractStatus = "disputed"
	StatusCancelled ContractStatus = "cancelled"
)

type MilestoneStatus string

const (
	MsPending   MilestoneStatus = "pending"
	MsFunded    MilestoneStatus = "funded"
	MsCompleted MilestoneStatus = "completed"
	MsReleased  MilestoneStatus = "released"
	MsDisputed  MilestoneStatus = "disputed"
	MsRefunded  MilestoneStatus = "refunded"
)

type Contract struct {
	ID          string
	Client      address
	Freelancer  address
	Title       string
	Description string
	Status      ContractStatus
	CreatedAt   int64 // block height
	Milestones  []Milestone
}

type Milestone struct {
	ID               int
	Title            string
	Amount           int64 // ugnot
	Status           MilestoneStatus
	FundedAt         int64           // block height (0 if not funded)
	CompletedAt      int64           // block height (0 if not completed)
	DisputedAt       int64           // block height (0 if not disputed)
	PreDisputeStatus MilestoneStatus // status before dispute (MsFunded or MsCompleted)
}

// ── State ────────────────────────────────────────────────────

var (
	contracts *avl.Tree // id -> *Contract
	nextID    int
	paused    bool
)

func init() {
	contracts = avl.NewTree()

	// Validate FeeRecipient at init — prevents fund-trapping panics later
	if len(FeeRecipient) == 0 {
		panic("FeeRecipient cannot be empty")
	}
}

// ── Emergency Pause ────────────────────────────────────────

func assertNotPaused() {
	if paused {
		panic("realm is paused — emergency maintenance")
	}
}

// Pause halts all write operations. Admin only.
func Pause(cur realm) {
	caller := unsafe.PreviousRealm().Address()
	if caller != address(AdminAddress) {
		panic("only admin can pause")
	}
	paused = true
}

// Unpause resumes normal operations. Admin only.
func Unpause(cur realm) {
	caller := unsafe.PreviousRealm().Address()
	if caller != address(AdminAddress) {
		panic("only admin can unpause")
	}
	paused = false
}

// IsPaused returns the current pause state.
func IsPaused() bool {
	return paused
}

// ── Contract Lifecycle ──────────────────────────────────────

// CreateContract creates a new escrow contract with milestones.
// Milestones format: "title1:amount1,title2:amount2"
func CreateContract(cur realm, freelancer address, title, description, milestones string) string {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()

	// Validations
	if freelancer == caller {
		panic("cannot hire yourself")
	}
	if len(title) == 0 || len(title) > MaxTitleLen {
		panic(ufmt.Sprintf("title must be 1-%d characters", MaxTitleLen))
	}
	if len(description) > MaxDescLen {
		panic(ufmt.Sprintf("description must be under %d characters", MaxDescLen))
	}
	if contracts.Size() >= MaxContracts {
		panic("contract limit reached")
	}

	ms := parseMilestones(milestones)
	if len(ms) == 0 {
		panic("at least one milestone required")
	}
	if len(ms) > MaxMilestones {
		panic(ufmt.Sprintf("maximum %d milestones allowed", MaxMilestones))
	}

	id := strconv.Itoa(nextID)
	nextID++

	c := &Contract{
		ID:          id,
		Client:      caller,
		Freelancer:  freelancer,
		Title:       sanitizeMilestoneTitle(title),
		Description: sanitizeMilestoneTitle(description),
		Status:      StatusActive,
		CreatedAt:   runtime.ChainHeight(),
		Milestones:  ms,
	}
	contracts.Set(id, c)

	chain.Emit("ContractCreated",
		"id", id,
		"client", caller.String(),
		"freelancer", freelancer.String(),
		"milestones", strconv.Itoa(len(ms)),
	)
	return id
}

// FundMilestone deposits funds for a specific milestone. Client only.
func FundMilestone(cur realm, contractId string, milestoneIdx int) {
	assertNotPaused()

	// P0 fund-guard: a payable entrypoint MUST be a direct user call. unsafe.OriginSend()
	// reports the tx-level `--send`, credited to the DIRECT message target realm — not to
	// an inner realm reached via a cross-call. Without this guard an attacker funds a
	// milestone through their own intermediary realm (coins land there), the escrow marks
	// the milestone funded though it received nothing, then the attacker extracts real
	// pooled client funds via ReleaseFunds/ClaimRefund. Requiring a direct user call forces
	// this realm to be the message target, the one case where the OriginSend coins are its own.
	if !unsafe.PreviousRealm().IsUserCall() {
		panic("FundMilestone must be a direct user call")
	}

	caller := unsafe.PreviousRealm().Address()
	c := getContract(contractId)

	if c.Client != caller {
		panic("only client can fund")
	}
	if c.Status != StatusActive {
		panic("contract not active")
	}
	if milestoneIdx < 0 || milestoneIdx >= len(c.Milestones) {
		panic("invalid milestone index")
	}

	ms := &c.Milestones[milestoneIdx]
	if ms.Status != MsPending {
		panic("milestone already funded or processed")
	}

	// Verify coins sent (accumulate to handle multi-entry defensively)
	sent := unsafe.OriginSend()
	sentAmount := int64(0)
	for _, coin := range sent {
		if coin.Denom == "ugnot" {
			sentAmount += coin.Amount
		}
	}
	if sentAmount != ms.Amount {
		panic(ufmt.Sprintf("must send exactly %d ugnot (sent %d)", ms.Amount, sentAmount))
	}

	ms.Status = MsFunded
	ms.FundedAt = runtime.ChainHeight()
	contracts.Set(contractId, c)

	chain.Emit("MilestoneFunded",
		"contractId", contractId,
		"milestone", strconv.Itoa(milestoneIdx),
		"amount", strconv.FormatInt(ms.Amount, 10),
	)
}

// CompleteMilestone marks a milestone as completed. Freelancer only.
func CompleteMilestone(cur realm, contractId string, milestoneIdx int) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()
	c := getContract(contractId)

	if c.Freelancer != caller {
		panic("only freelancer can mark complete")
	}
	// Only allow completion when contract is Active. Disputed contracts are frozen
	// until ResolveDispute/ClaimDisputeTimeout returns the contract to Active.
	if c.Status != StatusActive {
		panic("contract is " + string(c.Status) + " — cannot complete milestones during dispute")
	}
	if milestoneIdx < 0 || milestoneIdx >= len(c.Milestones) {
		panic("invalid milestone index")
	}

	ms := &c.Milestones[milestoneIdx]
	if ms.Status != MsFunded {
		panic("milestone not funded")
	}

	ms.Status = MsCompleted
	ms.CompletedAt = runtime.ChainHeight()
	contracts.Set(contractId, c)

	chain.Emit("MilestoneCompleted",
		"contractId", contractId,
		"milestone", strconv.Itoa(milestoneIdx),
		"freelancer", caller.String(),
	)
}

// ReleaseFunds releases funds to freelancer after client approves. Client or Admin.
func ReleaseFunds(cur realm, contractId string, milestoneIdx int) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()
	c := getContract(contractId)

	if c.Client != caller && caller != address(AdminAddress) {
		panic("only client or admin can release")
	}
	// Only allow release when contract is Active. Disputed contracts are frozen
	// until ResolveDispute/ClaimDisputeTimeout returns the contract to Active.
	if c.Status != StatusActive {
		panic("contract is " + string(c.Status) + " — cannot release funds during dispute")
	}
	if milestoneIdx < 0 || milestoneIdx >= len(c.Milestones) {
		panic("invalid milestone index")
	}

	ms := &c.Milestones[milestoneIdx]
	if ms.Status != MsCompleted {
		panic("milestone not completed")
	}

	// Calculate fees
	platformAmount := (ms.Amount * int64(PlatformFeePct)) / 100
	freelancerAmount := ms.Amount - platformAmount

	// STATE-BEFORE-SEND: update all state before any coin transfers
	ms.Status = MsReleased
	if allMilestonesReleased(c) {
		c.Status = StatusCompleted
	}
	contracts.Set(contractId, c)

	// Transfer funds
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	realmAddr := unsafe.CurrentRealm().Address()

	bnk.SendCoins(realmAddr, c.Freelancer, chain.Coins{chain.NewCoin("ugnot", freelancerAmount)})
	if platformAmount > 0 {
		bnk.SendCoins(realmAddr, address(FeeRecipient), chain.Coins{chain.NewCoin("ugnot", platformAmount)})
	}

	chain.Emit("FundsReleased",
		"contractId", contractId,
		"milestone", strconv.Itoa(milestoneIdx),
		"freelancer", c.Freelancer.String(),
		"amount", strconv.FormatInt(freelancerAmount, 10),
		"fee", strconv.FormatInt(platformAmount, 10),
	)
}

// ── Disputes ────────────────────────────────────────────────

// RaiseDispute escalates a milestone to admin arbitration. Client or Freelancer.
func RaiseDispute(cur realm, contractId string, milestoneIdx int) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()
	c := getContract(contractId)

	if c.Client != caller && c.Freelancer != caller {
		panic("only client or freelancer can dispute")
	}
	if c.Status == StatusCancelled || c.Status == StatusCompleted {
		panic("contract is " + string(c.Status))
	}
	if milestoneIdx < 0 || milestoneIdx >= len(c.Milestones) {
		panic("invalid milestone index")
	}

	ms := &c.Milestones[milestoneIdx]
	if ms.Status != MsFunded && ms.Status != MsCompleted {
		panic("can only dispute funded or completed milestones")
	}

	// Capture pre-dispute status so ClaimDisputeTimeout can resolve fairly:
	// if work was delivered (MsCompleted), pay freelancer; if not (MsFunded), refund client.
	ms.PreDisputeStatus = ms.Status
	ms.Status = MsDisputed
	ms.DisputedAt = runtime.ChainHeight()
	c.Status = StatusDisputed
	contracts.Set(contractId, c)

	chain.Emit("DisputeRaised",
		"contractId", contractId,
		"milestone", strconv.Itoa(milestoneIdx),
		"raisedBy", caller.String(),
	)
}

// ResolveDispute resolves a dispute. Admin only.
// refundClient=true refunds to client, false pays freelancer.
func ResolveDispute(cur realm, contractId string, milestoneIdx int, refundClient bool) {
	caller := unsafe.PreviousRealm().Address()
	if caller != address(AdminAddress) {
		panic("only admin can resolve disputes")
	}

	c := getContract(contractId)
	if milestoneIdx < 0 || milestoneIdx >= len(c.Milestones) {
		panic("invalid milestone index")
	}

	ms := &c.Milestones[milestoneIdx]
	if ms.Status != MsDisputed {
		panic("milestone not in dispute")
	}

	// STATE-BEFORE-SEND: update state before transfers
	if refundClient {
		ms.Status = MsRefunded
	} else {
		ms.Status = MsReleased
	}
	// Reset contract status if no other milestones are disputed
	c.Status = StatusActive
	for _, m := range c.Milestones {
		if m.Status == MsDisputed {
			c.Status = StatusDisputed
			break
		}
	}
	if allMilestonesReleased(c) {
		c.Status = StatusCompleted
	}
	contracts.Set(contractId, c)

	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	realmAddr := unsafe.CurrentRealm().Address()

	if refundClient {
		bnk.SendCoins(realmAddr, c.Client, chain.Coins{chain.NewCoin("ugnot", ms.Amount)})
	} else {
		platformAmount := (ms.Amount * int64(PlatformFeePct)) / 100
		freelancerAmount := ms.Amount - platformAmount
		bnk.SendCoins(realmAddr, c.Freelancer, chain.Coins{chain.NewCoin("ugnot", freelancerAmount)})
		if platformAmount > 0 {
			bnk.SendCoins(realmAddr, address(FeeRecipient), chain.Coins{chain.NewCoin("ugnot", platformAmount)})
		}
	}

	resolution := "released-to-freelancer"
	if refundClient {
		resolution = "refunded-to-client"
	}
	chain.Emit("DisputeResolved",
		"contractId", contractId,
		"milestone", strconv.Itoa(milestoneIdx),
		"resolution", resolution,
	)
}

// ── Cancellation ────────────────────────────────────────────

// CancelContract cancels an active contract. Client only.
// Funded milestones are refunded minus cancellation fee.
func CancelContract(cur realm, contractId string) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()
	c := getContract(contractId)

	if c.Client != caller {
		panic("only client can cancel")
	}
	if c.Status != StatusActive {
		panic("contract not active")
	}

	// STATE-BEFORE-SEND: update all state before transfers.
	// Track which milestones are NEWLY transitioned so we only pay those,
	// preventing double-refund of milestones already resolved via ResolveDispute.
	c.Status = StatusCancelled
	var newlyRefunded []int
	var newlyReleased []int
	for i := range c.Milestones {
		if c.Milestones[i].Status == MsFunded {
			c.Milestones[i].Status = MsRefunded
			newlyRefunded = append(newlyRefunded, i)
		} else if c.Milestones[i].Status == MsCompleted {
			c.Milestones[i].Status = MsReleased
			newlyReleased = append(newlyReleased, i)
		}
		// Already-terminal milestones (MsRefunded from ResolveDispute, MsReleased from
		// ReleaseFunds) are NOT added to the payment lists — their funds were already
		// distributed in the original operation.
	}
	contracts.Set(contractId, c)

	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	realmAddr := unsafe.CurrentRealm().Address()

	for _, i := range newlyRefunded {
		ms := c.Milestones[i]
		// Refund funded milestones minus cancellation fee
		fee := (ms.Amount * int64(CancelFeePct)) / 100
		refund := ms.Amount - fee
		if refund > 0 {
			bnk.SendCoins(realmAddr, c.Client, chain.Coins{chain.NewCoin("ugnot", refund)})
		}
		// Cancellation fee goes to freelancer as compensation for lost opportunity
		if fee > 0 {
			bnk.SendCoins(realmAddr, c.Freelancer, chain.Coins{chain.NewCoin("ugnot", fee)})
		}
	}
	for _, i := range newlyReleased {
		ms := c.Milestones[i]
		// Pay freelancer for completed work (full amount minus platform fee)
		platformAmount := (ms.Amount * int64(PlatformFeePct)) / 100
		freelancerAmount := ms.Amount - platformAmount
		bnk.SendCoins(realmAddr, c.Freelancer, chain.Coins{chain.NewCoin("ugnot", freelancerAmount)})
		if platformAmount > 0 {
			bnk.SendCoins(realmAddr, address(FeeRecipient), chain.Coins{chain.NewCoin("ugnot", platformAmount)})
		}
	}
}

// ── Timeouts (permissionless) ───────────────────────────────

// ClaimRefund refunds a funded milestone that has timed out.
// Anyone can call — permissionless, prevents fund locking.
func ClaimRefund(cur realm, contractId string, milestoneIdx int) {
	c := getContract(contractId)

	if milestoneIdx < 0 || milestoneIdx >= len(c.Milestones) {
		panic("invalid milestone index")
	}

	ms := &c.Milestones[milestoneIdx]
	if ms.Status != MsFunded {
		panic("milestone not funded")
	}
	if ms.FundedAt == 0 {
		panic("milestone has no funding record")
	}

	elapsed := runtime.ChainHeight() - ms.FundedAt
	if elapsed < AutoRefundBlks {
		panic(ufmt.Sprintf("too early: %d blocks remaining", AutoRefundBlks-elapsed))
	}

	// STATE-BEFORE-SEND
	ms.Status = MsRefunded
	// Update contract status if all milestones are now terminal
	if allMilestonesTerminal(c) {
		c.Status = StatusCancelled
	}
	contracts.Set(contractId, c)

	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(
		unsafe.CurrentRealm().Address(),
		c.Client,
		chain.Coins{chain.NewCoin("ugnot", ms.Amount)},
	)
}

// ClaimDisputeTimeout auto-resolves a dispute that admin hasn't acted on after
// AutoResolveBlks (~28 days). Resolution follows the pre-dispute status:
//   - If the milestone was MsCompleted (freelancer delivered work) before dispute,
//     funds go to freelancer (minus platform fee). This prevents griefing where
//     a client disputes after delivery and simply waits out the clock.
//   - If the milestone was MsFunded (work not yet delivered) before dispute,
//     funds are refunded to client.
// Anyone can call (permissionless safety valve).
func ClaimDisputeTimeout(cur realm, contractId string, milestoneIdx int) {
	c := getContract(contractId)

	if milestoneIdx < 0 || milestoneIdx >= len(c.Milestones) {
		panic("invalid milestone index")
	}

	ms := &c.Milestones[milestoneIdx]
	if ms.Status != MsDisputed {
		panic("milestone not in dispute")
	}
	if ms.DisputedAt == 0 {
		panic("milestone has no dispute record")
	}

	elapsed := runtime.ChainHeight() - ms.DisputedAt
	if elapsed < AutoResolveBlks {
		panic(ufmt.Sprintf("too early: %d blocks remaining", AutoResolveBlks-elapsed))
	}

	// Resolve based on pre-dispute status — fair to both parties.
	payFreelancer := ms.PreDisputeStatus == MsCompleted

	// STATE-BEFORE-SEND
	if payFreelancer {
		ms.Status = MsReleased
	} else {
		ms.Status = MsRefunded
	}
	// Reset contract status
	c.Status = StatusActive
	for _, m := range c.Milestones {
		if m.Status == MsDisputed {
			c.Status = StatusDisputed
			break
		}
	}
	if allMilestonesReleased(c) {
		c.Status = StatusCompleted
	} else if allMilestonesTerminal(c) {
		c.Status = StatusCancelled
	}
	contracts.Set(contractId, c)

	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	realmAddr := unsafe.CurrentRealm().Address()

	if payFreelancer {
		// Work was delivered — pay freelancer minus platform fee
		platformAmount := (ms.Amount * int64(PlatformFeePct)) / 100
		freelancerAmount := ms.Amount - platformAmount
		bnk.SendCoins(realmAddr, c.Freelancer, chain.Coins{chain.NewCoin("ugnot", freelancerAmount)})
		if platformAmount > 0 {
			bnk.SendCoins(realmAddr, address(FeeRecipient), chain.Coins{chain.NewCoin("ugnot", platformAmount)})
		}
		chain.Emit("DisputeTimedOut",
			"contractId", contractId,
			"milestone", strconv.Itoa(milestoneIdx),
			"resolution", "paid-freelancer-work-delivered",
		)
	} else {
		// Work never delivered — refund client in full
		bnk.SendCoins(realmAddr, c.Client, chain.Coins{chain.NewCoin("ugnot", ms.Amount)})
		chain.Emit("DisputeTimedOut",
			"contractId", contractId,
			"milestone", strconv.Itoa(milestoneIdx),
			"resolution", "refunded-client-no-delivery",
		)
	}
}

// ── Render ───────────────────────────────────────────────────

func Render(path string) string {
	if path == "" {
		return renderHome()
	}
	if strings.HasPrefix(path, "contract/") {
		id := strings.TrimPrefix(path, "contract/")
		return renderContract(id)
	}
	if path == "stats" {
		return renderStats()
	}
	return "# 404\nNot found: " + path
}

func renderHome() string {
	var sb strings.Builder
	sb.WriteString("# Escrow Contracts\n\n")
	sb.WriteString("Milestone-based escrow for freelance services on Gno.\n\n")

	if contracts.Size() == 0 {
		sb.WriteString("*No contracts yet.*\n")
		return sb.String()
	}

	sb.WriteString("| ID | Title | Client | Freelancer | Status | Total |\n")
	sb.WriteString("| --- | --- | --- | --- | --- | --- |\n")

	contracts.Iterate("", "", func(key string, value interface{}) bool {
		c := value.(*Contract)
		total := int64(0)
		for _, ms := range c.Milestones {
			total += ms.Amount
		}
		sb.WriteString(ufmt.Sprintf("| %s | [%s](:contract/%s) | %s | %s | %s | %d ugnot |\n",
			c.ID, c.Title, c.ID, truncAddr(c.Client), truncAddr(c.Freelancer),
			string(c.Status), total))
		return false
	})

	return sb.String()
}

func renderContract(id string) string {
	val, exists := contracts.Get(id)
	if !exists {
		return "# 404\nContract not found: " + id
	}
	c := val.(*Contract)

	var sb strings.Builder
	sb.WriteString("# " + c.Title + "\n\n")
	if len(c.Description) > 0 {
		sb.WriteString(c.Description + "\n\n")
	}
	sb.WriteString("**ID:** " + c.ID + "\n")
	sb.WriteString("**Client:** " + c.Client.String() + "\n")
	sb.WriteString("**Freelancer:** " + c.Freelancer.String() + "\n")
	sb.WriteString("**Status:** " + string(c.Status) + "\n")
	sb.WriteString("**Created:** block " + strconv.FormatInt(c.CreatedAt, 10) + "\n\n")

	total := int64(0)
	for _, ms := range c.Milestones {
		total += ms.Amount
	}
	sb.WriteString("**Total Value:** " + strconv.FormatInt(total, 10) + " ugnot\n\n")

	sb.WriteString("## Milestones\n\n")
	for _, ms := range c.Milestones {
		sb.WriteString(ufmt.Sprintf("- **%s** — %d ugnot [%s]",
			ms.Title, ms.Amount, string(ms.Status)))
		if ms.FundedAt > 0 {
			sb.WriteString(ufmt.Sprintf(" (funded block %d)", ms.FundedAt))
		}
		if ms.CompletedAt > 0 {
			sb.WriteString(ufmt.Sprintf(" (completed block %d)", ms.CompletedAt))
		}
		if ms.DisputedAt > 0 {
			sb.WriteString(ufmt.Sprintf(" (disputed block %d)", ms.DisputedAt))
		}
		sb.WriteString("\n")
	}

	return sb.String()
}

func renderStats() string {
	var sb strings.Builder
	sb.WriteString("# Escrow Stats\n\n")

	totalContracts := contracts.Size()
	active, completed, disputed, cancelled := 0, 0, 0, 0
	totalValue := int64(0)

	contracts.Iterate("", "", func(key string, value interface{}) bool {
		c := value.(*Contract)
		switch c.Status {
		case StatusActive:
			active++
		case StatusCompleted:
			completed++
		case StatusDisputed:
			disputed++
		case StatusCancelled:
			cancelled++
		}
		for _, ms := range c.Milestones {
			totalValue += ms.Amount
		}
		return false
	})

	sb.WriteString(ufmt.Sprintf("**Total Contracts:** %d\n", totalContracts))
	sb.WriteString(ufmt.Sprintf("**Active:** %d | **Completed:** %d | **Disputed:** %d | **Cancelled:** %d\n", active, completed, disputed, cancelled))
	sb.WriteString(ufmt.Sprintf("**Total Value:** %d ugnot\n", totalValue))

	return sb.String()
}

// ── Helpers ──────────────────────────────────────────────────

func getContract(id string) *Contract {
	val, exists := contracts.Get(id)
	if !exists {
		panic("contract not found: " + id)
	}
	return val.(*Contract)
}

func allMilestonesReleased(c *Contract) bool {
	for _, m := range c.Milestones {
		if m.Status != MsReleased {
			return false
		}
	}
	return true
}

// allMilestonesTerminal returns true if every milestone is in a final state
// (released, refunded, or pending — pending with no funds is terminal).
func allMilestonesTerminal(c *Contract) bool {
	for _, m := range c.Milestones {
		if m.Status == MsFunded || m.Status == MsCompleted || m.Status == MsDisputed {
			return false
		}
	}
	return true
}

// parseMilestones parses "title1:amount1,title2:amount2" into Milestone slice.
// Invalid entries cause a panic (not silently skipped).
func parseMilestones(input string) []Milestone {
	var result []Milestone
	parts := strings.Split(input, ",")
	for i, p := range parts {
		p = strings.TrimSpace(p)
		if len(p) == 0 {
			continue
		}
		kv := strings.SplitN(p, ":", 2)
		if len(kv) != 2 {
			panic(ufmt.Sprintf("invalid milestone format at position %d: expected 'title:amount'", i))
		}
		title := strings.TrimSpace(kv[0])
		if len(title) == 0 {
			panic(ufmt.Sprintf("empty milestone title at position %d", i))
		}
		if len(title) > MaxTitleLen {
			panic(ufmt.Sprintf("milestone title too long at position %d: %d/%d chars", i, len(title), MaxTitleLen))
		}
		title = sanitizeMilestoneTitle(title)
		amount, err := strconv.ParseInt(strings.TrimSpace(kv[1]), 10, 64)
		if err != nil || amount <= 0 {
			panic(ufmt.Sprintf("invalid milestone amount at position %d: must be positive integer", i))
		}
		// Minimum milestone amount prevents fee evasion via integer truncation.
		// At 2% fee, amounts < 50 ugnot would pay 0 fee.
		if amount < MinMilestoneAmount {
			panic(ufmt.Sprintf("milestone amount too small at position %d: minimum %d ugnot", i, MinMilestoneAmount))
		}
		result = append(result, Milestone{
			ID:     i,
			Title:  title,
			Amount: amount,
			Status: MsPending,
		})
	}
	return result
}

func truncAddr(addr address) string {
	s := addr.String()
	if len(s) > 13 {
		return s[:10] + "..."
	}
	return s
}

// sanitizeMilestoneTitle strips markdown special characters to prevent injection
// in gnoweb Render output.
func sanitizeMilestoneTitle(s string) string {
	var out strings.Builder
	for _, c := range s {
		switch c {
		case '[', ']', '(', ')', '#', '*', '`', '!', '<', '>', '|', '\\', '_', '~', '\n', '\r', '\t':
			continue // strip markdown-sensitive characters and control whitespace
		default:
			out.WriteRune(c)
		}
	}
	return out.String()
}

package agent_registry_v2

// Agent Registry — On-chain AI Agent Marketplace for the Memba ecosystem.
//
// Agents self-register with MCP metadata (endpoint, transport, pricing).
// Anyone can query via Render() for agent listings.
// Reviews are stored on-chain with 1-5 star ratings.
// Pay-per-use agents support a prepaid credit system.
//
// Render() contract:
//
//   Home — Render(""):
//     # Memba Agent Registry
//     description
//     ## Agents
//     | ID | Name | Category | Rating | Pricing |
//     | --- | --- | --- | --- | --- |
//     | id | name | category | 4.2 (5) | free |
//
//   Agent — Render("agent/id"):
//     # AgentName
//     description
//     **Category:** category
//     **Creator:** g1addr
//     **Endpoint:** endpoint
//     **Transport:** stdio|sse|streamable-http
//     **Pricing:** free|pay-per-use|subscription
//     **Rating:** 4.2 (5 reviews)
//     ## Capabilities
//     - capability1
//     - capability2
//     ## Reviews
//     **g1addr...** stars (block H)
//     review text
//
//   Stats — Render("stats"):
//     Total agents, total reviews, total calls

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// ── Constants ────────────────────────────────────────────────

const (
	MaxAgents    = 100
	MaxNameLen   = 100
	MaxDescLen   = 1000
	MaxCapsLen   = 2000
	MaxReviewLen = 500
	// AR-1 render-DoS bound: reviews are sybil-growable (one per address, no cap), and
	// renderAgent previously iterated the entire slice — an attacker could make an agent
	// page unrenderable past the query gas cap. Render only the newest window.
	ReviewRenderMax = 20
	AdminAddress = "g1x7k4628w93a7wzdhqc06atzx0v50rnshweuxu0" // samcrew-core-test1 multisig

	// AAA-1 B4 — anti-squat + fund-lock-DoS bounds.
	// MaxAgentsPerCreator caps how many agents one address can register, so a
	// single funded address cannot squat the whole MaxAgents global supply.
	MaxAgentsPerCreator = 10
	// MaxDepositorsPerAgent bounds the distinct depositor set per agent. RemoveAgent
	// refunds EVERY depositor in one transaction (the credits prefix scan below); an
	// unbounded set would make RemoveAgent exceed the block gas budget and become
	// permanently uncallable, locking all deposited funds. At this cap the full
	// refund loop measures ≈3M gas in `gno test` — a small fraction of the block
	// budget, so RemoveAgent stays callable with wide headroom.
	MaxDepositorsPerAgent = 50
)

// ── Types ────────────────────────────────────────────────────

type Agent struct {
	ID           string
	Name         string
	Description  string
	Category     string
	Capabilities string // comma-separated
	Creator      address
	Endpoint     string
	Transport    string // "stdio" | "sse" | "streamable-http"
	Pricing      string // "free" | "pay-per-use" | "subscription"
	PricePerCall int64  // in ugnot (0 if free)
	Version      string
	TotalCalls   int64
	RatingSum    int64
	RatingCount  int64
	BlockH       int64
}

type Review struct {
	Reviewer address
	Rating   int // 1-5
	Comment  string
	BlockH   int64
}

// ── State ────────────────────────────────────────────────────

var (
	agents    *avl.Tree // id -> *Agent
	reviews   *avl.Tree // agentId -> []*Review
	reviewers *avl.Tree // "agentId/addr" -> true (dedup: one review per agent per address)
	credits   *avl.Tree // "agentId/userAddr" -> int64 (prepaid credits in ugnot)
	usage     *avl.Tree // "agentId/userAddr" -> int64 (total calls)
	earnings  *avl.Tree // agentId -> int64 (accumulated creator earnings in ugnot)
	paused    bool
)

func init() {
	agents = avl.NewTree()
	reviews = avl.NewTree()
	reviewers = avl.NewTree()
	credits = avl.NewTree()
	usage = avl.NewTree()
	earnings = avl.NewTree()
}

// ── Emergency Pause ────────────────────────────────────────
//
// Pause policy (AAA-1 B3 — one policy, enforced everywhere):
//   While paused, every state-mutating user operation is blocked
//   (RegisterAgent, UpdateAgent, ReviewAgent, RemoveAgent, DepositCredits,
//   UseCredit, WithdrawEarnings) via assertNotPaused().
//
//   EXEMPTION — RefundCredits is deliberately NOT gated: a user must always be
//   able to reclaim their own deposited principal, even during emergency
//   maintenance. A credit balance only ever equals real ugnot the user sent
//   (DepositCredits) minus what they spent (UseCredit), so refunding it is
//   always safe and never exploit-amplifying. WithdrawEarnings (creator profit,
//   which an exploit could inflate) stays blocked by design.

func assertNotPaused() {
	if paused {
		panic("realm is paused — emergency maintenance")
	}
}

// Pause blocks all state-mutating operations EXCEPT RefundCredits (users keep the
// right to reclaim their own deposits). Admin only. See the pause policy above.
func Pause(cur realm) {
	caller := unsafe.PreviousRealm().Address()
	if caller != address(AdminAddress) {
		panic("only admin can pause")
	}
	paused = true
}

// Unpause resumes normal operations. Admin only.
func Unpause(cur realm) {
	caller := unsafe.PreviousRealm().Address()
	if caller != address(AdminAddress) {
		panic("only admin can unpause")
	}
	paused = false
}

// IsPaused returns the current pause state.
func IsPaused() bool {
	return paused
}

// ── Public Functions ─────────────────────────────────────────

// RegisterAgent registers a new agent in the registry.
func RegisterAgent(
	cur realm,
	id, name, description, category, capabilities,
	endpoint, transport, pricing, version string,
	pricePerCall int64,
) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()

	if _, exists := agents.Get(id); exists {
		panic("agent ID already exists: " + id)
	}
	if len(id) == 0 || len(id) > 50 {
		panic("ID must be 1-50 characters")
	}
	if !isValidAgentID(id) {
		panic("ID must contain only alphanumeric characters, hyphens, or underscores")
	}
	if len(name) == 0 || len(name) > MaxNameLen {
		panic(ufmt.Sprintf("name must be 1-%d characters", MaxNameLen))
	}
	if len(description) > MaxDescLen {
		panic("description too long")
	}
	if len(capabilities) > MaxCapsLen {
		panic("capabilities too long")
	}
	if len(category) > MaxNameLen {
		panic("category too long")
	}
	if len(endpoint) > MaxDescLen {
		panic("endpoint too long")
	}
	if len(version) > 50 {
		panic("version too long")
	}
	if agents.Size() >= MaxAgents {
		panic("registry full")
	}
	// B4: per-creator cap — stop a single address squatting the global supply.
	if countAgentsByCreator(caller) >= MaxAgentsPerCreator {
		panic("creator agent limit reached")
	}
	if !isValidTransport(transport) {
		panic("transport must be stdio, sse, or streamable-http")
	}
	if !isValidPricing(pricing) {
		panic("pricing must be free, pay-per-use, or subscription")
	}
	if pricePerCall < 0 {
		panic("pricePerCall must be >= 0")
	}

	a := &Agent{
		ID:           id,
		Name:         name,
		Description:  description,
		Category:     category,
		Capabilities: capabilities,
		Creator:      caller,
		Endpoint:     endpoint,
		Transport:    transport,
		Pricing:      pricing,
		PricePerCall: pricePerCall,
		Version:      version,
		BlockH:       runtime.ChainHeight(),
	}
	agents.Set(id, a)
	reviews.Set(id, []*Review{})

	chain.Emit("AgentRegistered",
		"id", id,
		"name", name,
		"creator", caller.String(),
		"pricing", pricing,
	)
}

// UpdateAgent allows the creator to update their agent.
func UpdateAgent(
	cur realm,
	id, description, capabilities, endpoint, version, pricing string,
	pricePerCall int64,
) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()
	val, exists := agents.Get(id)
	if !exists {
		panic("agent not found: " + id)
	}
	a := val.(*Agent)
	if a.Creator != caller {
		panic("only the creator can update")
	}
	if len(description) > 0 {
		if len(description) > MaxDescLen {
			panic("description too long")
		}
		a.Description = description
	}
	if len(capabilities) > 0 {
		if len(capabilities) > MaxCapsLen {
			panic("capabilities too long")
		}
		a.Capabilities = capabilities
	}
	if len(endpoint) > 0 {
		a.Endpoint = endpoint
	}
	if len(version) > 0 {
		a.Version = version
	}
	if pricePerCall < 0 {
		panic("pricePerCall must be >= 0")
	}
	if len(pricing) > 0 {
		if !isValidPricing(pricing) {
			panic("pricing must be free, pay-per-use, or subscription")
		}
		// Prevent pricing model change when ANY credit entry exists for this agent,
		// including zero-balance entries. This closes the price-lock bypass where
		// the creator drains user balances to 0 then raises the price before the
		// user's next deposit lands.
		if pricing != a.Pricing && hasAnyCreditsEntry(id) {
			panic("cannot change pricing model while credit entries exist for this agent")
		}
		a.Pricing = pricing
	}
	if pricePerCall != a.PricePerCall && hasAnyCreditsEntry(id) {
		panic("cannot change price per call while credit entries exist for this agent")
	}
	a.PricePerCall = pricePerCall
	agents.Set(id, a)

	chain.Emit("AgentUpdated",
		"id", id,
		"creator", caller.String(),
	)
}

// ReviewAgent adds a review for an agent. One review per address per agent.
func ReviewAgent(cur realm, agentId string, rating int, comment string) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()

	val, exists := agents.Get(agentId)
	if !exists {
		panic("agent not found")
	}
	if rating < 1 || rating > 5 {
		panic("rating must be 1-5")
	}
	if len(comment) > MaxReviewLen {
		panic("review too long")
	}

	// Enforce one review per address per agent
	reviewKey := agentId + "/" + caller.String()
	if _, already := reviewers.Get(reviewKey); already {
		panic("already reviewed this agent")
	}
	reviewers.Set(reviewKey, true)

	a := val.(*Agent)
	a.RatingSum += int64(rating)
	a.RatingCount++
	agents.Set(agentId, a)

	rval, _ := reviews.Get(agentId)
	revs := rval.([]*Review)
	revs = append(revs, &Review{
		Reviewer: caller,
		Rating:   rating,
		Comment:  comment,
		BlockH:   runtime.ChainHeight(),
	})
	reviews.Set(agentId, revs)

	chain.Emit("AgentReviewed",
		"agentId", agentId,
		"reviewer", caller.String(),
		"rating", strconv.Itoa(rating),
	)
}

// RemoveAgent removes an agent (admin or creator only).
// All outstanding credits are refunded to their depositors before removal.
func RemoveAgent(cur realm, id string) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()
	val, exists := agents.Get(id)
	if !exists {
		panic("agent not found")
	}
	a := val.(*Agent)
	if a.Creator != caller && caller != address(AdminAddress) {
		panic("only creator or admin can remove")
	}

	// Refund all outstanding credits before removal.
	// Use prefix + "\xff" as exclusive upper bound for the AVL prefix scan —
	// any key starting with "id/" sorts strictly before "id/\xff".
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	realmAddr := unsafe.CurrentRealm().Address()
	prefix := id + "/"
	var creditsToRefund []string
	credits.Iterate(prefix, prefix+"\xff", func(key string, value interface{}) bool {
		creditsToRefund = append(creditsToRefund, key)
		return false
	})
	for _, key := range creditsToRefund {
		cval, cok := credits.Get(key)
		if !cok {
			continue
		}
		balance := cval.(int64)
		if balance > 0 {
			userAddr := key[len(prefix):]
			// STATE-BEFORE-SEND: zero balance before coin transfer
			credits.Set(key, int64(0))
			bnk.SendCoins(realmAddr, address(userAddr),
				chain.Coins{chain.NewCoin("ugnot", balance)})
		}
	}

	// Pay out the creator's accrued earnings BEFORE deleting the record.
	// UseCredit moves ugnot from credits -> earnings, so these are real funds
	// the realm holds; removing the record without paying would strand them
	// permanently (WithdrawEarnings would then panic "agent not found").
	if earned := GetEarnings(id); earned > 0 {
		earnings.Set(id, int64(0)) // STATE-BEFORE-SEND
		bnk.SendCoins(realmAddr, a.Creator,
			chain.Coins{chain.NewCoin("ugnot", earned)})
	}

	// Clean up orphaned state: earnings and usage entries for this agent
	earnings.Remove(id)
	// Clean up usage entries with this agent prefix
	usagePrefix := id + "/"
	var usageToRemove []string
	usage.Iterate(usagePrefix, usagePrefix+"\xff", func(k string, _ interface{}) bool {
		usageToRemove = append(usageToRemove, k)
		return false
	})
	for _, k := range usageToRemove {
		usage.Remove(k)
	}
	// Also clean up any zero-balance residual credit entries
	var creditsToRemove []string
	credits.Iterate(usagePrefix, usagePrefix+"\xff", func(k string, _ interface{}) bool {
		creditsToRemove = append(creditsToRemove, k)
		return false
	})
	for _, k := range creditsToRemove {
		credits.Remove(k)
	}

	agents.Remove(id)
	reviews.Remove(id)

	chain.Emit("AgentRemoved",
		"id", id,
		"remover", caller.String(),
	)
}

// ── Pay-Per-Use Credit System ────────────────────────────────

// DepositCredits deposits GNOT as prepaid credits for an agent.
// Send ugnot with the transaction to fund the credits.
func DepositCredits(cur realm, agentId string) {
	assertNotPaused()

	// P0 fund-guard: a payable entrypoint MUST be a direct user call. unsafe.OriginSend()
	// reports the tx-level `--send`, credited to the DIRECT message target realm — not to
	// an inner realm reached via a cross-call. Without this guard an attacker deposits
	// through their own intermediary realm (coins land there), this realm credits an amount
	// it never received, then the attacker drains real pooled prepaid credits via
	// RefundCredits/WithdrawEarnings. Requiring a direct user call forces this realm to be
	// the message target, the one case where the OriginSend coins are in its own account.
	if !unsafe.PreviousRealm().IsUserCall() {
		panic("DepositCredits must be a direct user call")
	}

	caller := unsafe.PreviousRealm().Address()
	if _, exists := agents.Get(agentId); !exists {
		panic("agent not found")
	}

	sent := unsafe.OriginSend()
	amount := int64(0)
	for _, coin := range sent {
		if coin.Denom == "ugnot" {
			amount += coin.Amount
		}
	}
	if amount == 0 {
		panic("must send ugnot to deposit credits")
	}

	key := agentId + "/" + caller.String()
	existing := int64(0)
	alreadyDepositor := false
	if val, ok := credits.Get(key); ok {
		existing = val.(int64)
		alreadyDepositor = true
	}
	// B4: bound the distinct depositor set so RemoveAgent's refund loop stays within
	// the gas budget. Existing depositors may always top up; only NEW depositors are
	// capped.
	if !alreadyDepositor && countDepositors(agentId) >= MaxDepositorsPerAgent {
		panic("agent depositor limit reached")
	}
	credits.Set(key, existing+amount)

	chain.Emit("CreditsDeposited",
		"agentId", agentId,
		"user", caller.String(),
		"amount", strconv.FormatInt(amount, 10),
	)
}

// UseCredit deducts one invocation credit. Only the agent creator or admin can call.
// Returns the remaining credits.
func UseCredit(cur realm, agentId, userAddr string) int64 {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()
	val, exists := agents.Get(agentId)
	if !exists {
		panic("agent not found")
	}
	a := val.(*Agent)

	// Only the agent creator (who runs the MCP backend) or platform admin
	// can deduct credits on behalf of users
	if a.Creator != caller && caller != address(AdminAddress) {
		panic("only agent creator or admin can deduct credits")
	}

	key := agentId + "/" + userAddr
	if a.Pricing == "pay-per-use" && a.PricePerCall > 0 {
		cval, cexists := credits.Get(key)
		if !cexists {
			panic("no credits deposited")
		}
		balance := cval.(int64)
		if balance < a.PricePerCall {
			panic(ufmt.Sprintf("insufficient credits: %d < %d", balance, a.PricePerCall))
		}
		credits.Set(key, balance-a.PricePerCall)

		// Track earnings for creator withdrawal
		earned := int64(0)
		if ev, eok := earnings.Get(agentId); eok {
			earned = ev.(int64)
		}
		earnings.Set(agentId, earned+a.PricePerCall)
	}

	// Track usage
	a.TotalCalls++
	agents.Set(agentId, a)

	uval := int64(0)
	if uv, uok := usage.Get(key); uok {
		uval = uv.(int64)
	}
	usage.Set(key, uval+1)

	remaining := int64(0)
	if rv, rok := credits.Get(key); rok {
		remaining = rv.(int64)
	}

	// B6: every state transition emits a typed event for indexers/agents.
	chain.Emit("CreditUsed",
		"agentId", agentId,
		"user", userAddr,
		"caller", caller.String(),
		"remaining", strconv.FormatInt(remaining, 10),
	)
	return remaining
}

// GetCredits returns the credit balance for a user on an agent.
func GetCredits(agentId, userAddr string) int64 {
	key := agentId + "/" + userAddr
	if val, ok := credits.Get(key); ok {
		return val.(int64)
	}
	return 0
}

// GetUsage returns the total invocation count for a user on an agent.
func GetUsage(agentId, userAddr string) int64 {
	key := agentId + "/" + userAddr
	if val, ok := usage.Get(key); ok {
		return val.(int64)
	}
	return 0
}

// GetEarnings returns accumulated earnings for an agent.
func GetEarnings(agentId string) int64 {
	if val, ok := earnings.Get(agentId); ok {
		return val.(int64)
	}
	return 0
}

// WithdrawEarnings allows the agent creator to withdraw accumulated usage fees.
// Earnings accumulate when UseCredit deducts from user credit balances.
func WithdrawEarnings(cur realm, agentId string) {
	assertNotPaused()
	caller := unsafe.PreviousRealm().Address()
	val, exists := agents.Get(agentId)
	if !exists {
		panic("agent not found")
	}
	a := val.(*Agent)
	if a.Creator != caller {
		panic("only agent creator can withdraw earnings")
	}

	earned := int64(0)
	if ev, eok := earnings.Get(agentId); eok {
		earned = ev.(int64)
	}
	if earned == 0 {
		panic("no earnings to withdraw")
	}

	// STATE-BEFORE-SEND: zero earnings before coin transfer
	earnings.Set(agentId, int64(0))

	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(
		unsafe.CurrentRealm().Address(),
		caller,
		chain.Coins{chain.NewCoin("ugnot", earned)},
	)

	chain.Emit("EarningsWithdrawn",
		"agentId", agentId,
		"creator", caller.String(),
		"amount", strconv.FormatInt(earned, 10),
	)
}

// RefundCredits refunds remaining credits to the caller.
func RefundCredits(cur realm, agentId string) {
	caller := unsafe.PreviousRealm().Address()
	key := agentId + "/" + caller.String()

	cval, cexists := credits.Get(key)
	if !cexists {
		panic("no credits to refund")
	}
	balance := cval.(int64)
	if balance == 0 {
		panic("zero balance")
	}

	// STATE-BEFORE-SEND: fully REMOVE the entry (not just zero it) so that the
	// pricing lock in UpdateAgent doesn't remain triggered after a full refund.
	credits.Remove(key)

	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(
		unsafe.CurrentRealm().Address(),
		caller,
		chain.Coins{chain.NewCoin("ugnot", balance)},
	)

	chain.Emit("CreditsRefunded",
		"agentId", agentId,
		"user", caller.String(),
		"amount", strconv.FormatInt(balance, 10),
	)
}

// ── Render ───────────────────────────────────────────────────

func Render(path string) string {
	if path == "" {
		return renderHome()
	}
	if path == "stats" {
		return renderStats()
	}
	if strings.HasPrefix(path, "agent/") {
		agentId := strings.TrimPrefix(path, "agent/")
		return renderAgent(agentId)
	}
	return "# 404\nNot found: " + path
}

func renderHome() string {
	var sb strings.Builder
	sb.WriteString("# Memba Agent Registry\n\n")
	sb.WriteString("On-chain AI Agent Marketplace for the Gno ecosystem.\n\n")

	if agents.Size() == 0 {
		sb.WriteString("*No agents registered yet.*\n")
		return sb.String()
	}

	sb.WriteString("## Agents\n\n")
	sb.WriteString("| ID | Name | Category | Rating | Pricing |\n")
	sb.WriteString("| --- | --- | --- | --- | --- |\n")

	agents.Iterate("", "", func(key string, value interface{}) bool {
		a := value.(*Agent)
		rating := "unrated"
		if a.RatingCount > 0 {
			rating = formatRating(a.RatingSum, a.RatingCount)
		}
		pricing := a.Pricing
		if a.Pricing == "pay-per-use" && a.PricePerCall > 0 {
			pricing = ufmt.Sprintf("pay-per-use (%d ugnot)", a.PricePerCall)
		}
		sb.WriteString(ufmt.Sprintf("| %s | [%s](:agent/%s) | %s | %s | %s |\n",
			a.ID, sanitizeForRender(a.Name), a.ID, sanitizeForRender(a.Category), rating, pricing))
		return false
	})

	return sb.String()
}

func renderAgent(id string) string {
	val, exists := agents.Get(id)
	if !exists {
		return "# 404\nAgent not found: " + id
	}
	a := val.(*Agent)

	var sb strings.Builder
	sb.WriteString("# " + sanitizeForRender(a.Name) + "\n\n")
	sb.WriteString(sanitizeForRender(a.Description) + "\n\n")
	sb.WriteString("**ID:** " + a.ID + "\n")
	sb.WriteString("**Category:** " + sanitizeForRender(a.Category) + "\n")
	sb.WriteString("**Creator:** " + a.Creator.String() + "\n")
	sb.WriteString("**Endpoint:** " + sanitizeForRender(a.Endpoint) + "\n")
	sb.WriteString("**Transport:** " + a.Transport + "\n")
	sb.WriteString("**Pricing:** " + a.Pricing + "\n")
	if a.PricePerCall > 0 {
		sb.WriteString("**Price:** " + strconv.FormatInt(a.PricePerCall, 10) + " ugnot/call\n")
	}
	sb.WriteString("**Version:** " + sanitizeForRender(a.Version) + "\n")
	sb.WriteString("**Total Calls:** " + strconv.FormatInt(a.TotalCalls, 10) + "\n")
	sb.WriteString("**Registered:** block " + strconv.FormatInt(a.BlockH, 10) + "\n")

	if a.RatingCount > 0 {
		sb.WriteString("**Rating:** " + formatRating(a.RatingSum, a.RatingCount) +
			" (" + strconv.FormatInt(a.RatingCount, 10) + " reviews)\n")
	}

	// Capabilities
	sb.WriteString("\n## Capabilities\n\n")
	for _, cap := range strings.Split(a.Capabilities, ",") {
		cap = strings.TrimSpace(cap)
		if len(cap) > 0 {
			sb.WriteString("- " + sanitizeForRender(cap) + "\n")
		}
	}

	// Reviews — AR-1: render only the newest ReviewRenderMax so a sybil review flood can't
	// make this page exceed the query gas cap. AR-2: every user-controlled field sanitized.
	rval, rexists := reviews.Get(id)
	if rexists {
		revs := rval.([]*Review)
		if len(revs) > 0 {
			sb.WriteString("\n## Reviews\n\n")
			start := 0
			if len(revs) > ReviewRenderMax {
				start = len(revs) - ReviewRenderMax
				sb.WriteString(ufmt.Sprintf("_showing newest %d of %d reviews_\n\n",
					ReviewRenderMax, len(revs)))
			}
			for _, r := range revs[start:] {
				stars := strings.Repeat("*", r.Rating) + strings.Repeat(".", 5-r.Rating)
				sb.WriteString(ufmt.Sprintf("**%s** [%s] (block %d)\n\n",
					truncAddr(r.Reviewer), stars, r.BlockH))
				if len(r.Comment) > 0 {
					sb.WriteString(sanitizeForRender(r.Comment) + "\n\n")
				}
				sb.WriteString("---\n\n")
			}
		}
	}

	return sb.String()
}

func renderStats() string {
	var sb strings.Builder
	sb.WriteString("# Registry Stats\n\n")

	totalAgents := agents.Size()
	totalReviews := int64(0)
	totalCalls := int64(0)

	agents.Iterate("", "", func(key string, value interface{}) bool {
		a := value.(*Agent)
		totalReviews += a.RatingCount
		totalCalls += a.TotalCalls
		return false
	})

	sb.WriteString(ufmt.Sprintf("**Total Agents:** %d\n", totalAgents))
	sb.WriteString(ufmt.Sprintf("**Total Reviews:** %d\n", totalReviews))
	sb.WriteString(ufmt.Sprintf("**Total Calls:** %d\n", totalCalls))

	return sb.String()
}

// ── Helpers ──────────────────────────────────────────────────

// formatRating formats a rating as "X.Y" using integer math (no float in ufmt).
func formatRating(sum, count int64) string {
	if count == 0 {
		return "0.0"
	}
	whole := sum / count
	// One decimal place: (sum * 10 / count) % 10
	frac := ((sum * 10) / count) % 10
	return strconv.FormatInt(whole, 10) + "." + strconv.FormatInt(frac, 10)
}

func truncAddr(addr address) string {
	s := addr.String()
	if len(s) > 13 {
		return s[:10] + "..."
	}
	return s
}

func isValidTransport(t string) bool {
	return t == "stdio" || t == "sse" || t == "streamable-http"
}

func isValidPricing(p string) bool {
	return p == "free" || p == "pay-per-use" || p == "subscription"
}

// sanitizeForRender strips markdown-sensitive characters from user-controlled strings
// before rendering in gnoweb to prevent injection attacks.
func sanitizeForRender(s string) string {
	var out strings.Builder
	for _, c := range s {
		switch c {
		case '[', ']', '(', ')', '#', '*', '`', '!', '<', '>', '|', '\\', '_', '~', '\n', '\r', '\t':
			continue
		default:
			out.WriteRune(c)
		}
	}
	return out.String()
}

// countAgentsByCreator counts how many agents `creator` currently owns (B4 cap).
// Bounded by MaxAgents (global), so O(MaxAgents) worst case.
func countAgentsByCreator(creator address) int {
	n := 0
	agents.Iterate("", "", func(_ string, value interface{}) bool {
		if value.(*Agent).Creator == creator {
			n++
		}
		return false
	})
	return n
}

// countDepositors counts the distinct credit entries for an agent (B4 cap).
// Bounded by MaxDepositorsPerAgent in steady state (the cap enforces its own
// bound), so the scan stays cheap.
func countDepositors(agentId string) int {
	prefix := agentId + "/"
	n := 0
	credits.Iterate(prefix, prefix+"\xff", func(_ string, _ interface{}) bool {
		n++
		return false
	})
	return n
}

// hasAnyCreditsEntry returns true if ANY credit entry exists for the agent,
// even with zero balance. This prevents a price-lock bypass where the creator
// drains a user's balance to 0, then raises the price, then the user tops up.
// Zero-balance entries remain as markers until explicitly cleaned via
// RefundCredits (which removes the entry) or RemoveAgent.
func hasAnyCreditsEntry(agentId string) bool {
	prefix := agentId + "/"
	found := false
	credits.Iterate(prefix, prefix+"\xff", func(key string, value interface{}) bool {
		found = true
		return true // stop iteration
	})
	return found
}

// isValidAgentID ensures the ID contains only safe characters (no "/" or other delimiters
// that would cause key collisions in the credits/usage AVL trees).
func isValidAgentID(id string) bool {
	for _, c := range id {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-' || c == '_') {
			return false
		}
	}
	return true
}

package memba_token_otc_v2

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
	"gno.land/r/samcrew/memba_market_config"
	"gno.land/r/samcrew/tokenfactory_v2"
)

// AdminAddress is the same 2-of-2 multisig used by the market config.
const AdminAddress = "g10kw7e55e9wc8j8v6904ck29dqwr9fm9u280juh"

type Listing struct {
	Id        uint64
	Seller    address
	Symbol    string
	Amount    int64
	UnitPrice int64
	CreatedAt int64
}

var (
	admin         address
	paused        bool
	listings      avl.Tree // uint64 -> *Listing
	nextListingId uint64 = 1
)

func init() {
	admin = address(AdminAddress)
}

func caller() address { return unsafe.PreviousRealm().Address() }

// Pause acts as the kill switch for the engine (stops listing and filling).
func Pause(cur realm, state bool) {
	if caller() != admin {
		panic("unauthorized")
	}
	paused = state
}

// ListTokens creates a new OTC listing for a tokenfactory_v2 token.
func ListTokens(cur realm, symbol string, amount, unitPrice int64) uint64 {
	if paused {
		panic("engine is paused")
	}
	if amount <= 0 {
		panic("amount must be > 0")
	}
	if unitPrice <= 0 {
		panic("unitPrice must be > 0")
	}

	seller := caller()

	// SECURITY: Ensure the token was minted by tokenfactory_v2.
	// Bank will panic if the symbol is not registered in the factory.
	_ = tokenfactory_v2.Bank(symbol)

	// Verify the seller has enough balance and has approved this realm.
	bal := tokenfactory_v2.BalanceOf(symbol, seller)
	if bal < amount {
		panic("insufficient token balance")
	}
	allow := tokenfactory_v2.Allowance(symbol, seller, cur.Address())
	if allow < amount {
		panic("insufficient token allowance granted to OTC realm")
	}

	id := nextListingId
	nextListingId++

	listing := &Listing{
		Id:        id,
		Seller:    seller,
		Symbol:    symbol,
		Amount:    amount,
		UnitPrice: unitPrice,
		CreatedAt: runtime.ChainHeight(),
	}

	listings.Set(ufmt.Sprintf("%d", id), listing)

	chain.Emit("Listed",
		"id", ufmt.Sprintf("%d", id),
		"seller", string(seller),
		"symbol", symbol,
		"amount", ufmt.Sprintf("%d", amount),
		"unitPrice", ufmt.Sprintf("%d", unitPrice),
	)

	return id
}

// CancelListing removes an OTC listing. Only the seller can cancel.
func CancelListing(cur realm, listingId uint64) {
	seller := caller()
	listingRaw, exists := listings.Get(ufmt.Sprintf("%d", listingId))
	if !exists {
		panic("listing not found")
	}
	listing := listingRaw.(*Listing)

	if listing.Seller != seller {
		panic("unauthorized: not the seller")
	}

	listings.Remove(ufmt.Sprintf("%d", listingId))

	chain.Emit("Cancelled",
		"id", ufmt.Sprintf("%d", listingId),
	)
}

// Fill executes a partial or full fill of an OTC listing.
func Fill(cur realm, listingId uint64, qty, expectedUnitPrice int64) {
	if paused {
		panic("engine is paused")
	}

	// P0 fund-guard: a payable entrypoint MUST be a direct user call. unsafe.OriginSend()
	// reports the tx-level `--send`, credited to the DIRECT message target realm — not to
	// an inner realm reached via a cross-call. This realm forwards funds immediately and
	// holds no standing pool, so a routed fill self-reverts today (MED) — but the guard is
	// applied uniformly with the other payable entrypoints to close the residual-balance
	// edge (stranded/donated ugnot) and prevent regressions.
	if !unsafe.PreviousRealm().IsUserCall() {
		panic("Fill must be a direct user call")
	}

	if qty <= 0 {
		panic("qty must be > 0")
	}

	buyer := caller()

	listingRaw, exists := listings.Get(ufmt.Sprintf("%d", listingId))
	if !exists {
		panic("listing not found")
	}
	listing := listingRaw.(*Listing)

	// Slippage & front-run protection
	if listing.UnitPrice != expectedUnitPrice {
		panic("price mismatch (front-run protection)")
	}

	if listing.Amount < qty {
		panic("requested qty exceeds available listing amount")
	}

	// Verify seller still has balance and allowance
	bal := tokenfactory_v2.BalanceOf(listing.Symbol, listing.Seller)
	if bal < qty {
		panic("seller has insufficient balance")
	}
	allow := tokenfactory_v2.Allowance(listing.Symbol, listing.Seller, cur.Address())
	if allow < qty {
		panic("seller has insufficient allowance")
	}

	// Calculate cost — guard the int64 multiplication against overflow. qty>0 (checked
	// above) and unitPrice>0 (checked at ListTokens), so a valid product is >0 and
	// cost/qty == unitPrice; a wrapped product fails one of those.
	cost := qty * listing.UnitPrice
	if cost <= 0 || cost/qty != listing.UnitPrice {
		panic("cost overflow")
	}

	// Dust-fill evasion protection (e.g., minimum notional > 0 if fee > 0)
	feeBps, treasury := memba_market_config.GetLaneConfig("token")
	if feeBps > int(memba_market_config.MaxFeeBPS) {
		feeBps = int(memba_market_config.DefaultFeeBPS) // safe fallback clamp
	}

	fee := (cost * int64(feeBps)) / 10000
	if feeBps > 0 && fee == 0 {
		panic("dust fill: notional too small to cover minimum fee")
	}

	// Require EXACT payment sent WITH this call. Read OriginSend (the coins attached to
	// the call) — NOT the caller's wallet balance — mirroring escrow_v2.FundMilestone.
	// Exact-coin closes both the overpay-trap (excess had no refund/sweep) and the
	// wallet-balance bypass (a funded caller could trigger a payout without paying).
	sent := unsafe.OriginSend()
	if sent.AmountOf("ugnot") != cost {
		panic(ufmt.Sprintf("must send exactly %d ugnot (sent %d)", cost, sent.AmountOf("ugnot")))
	}

	// CEI: Update state first
	listing.Amount -= qty
	if listing.Amount == 0 {
		listings.Remove(ufmt.Sprintf("%d", listingId))
	} else {
		listings.Set(ufmt.Sprintf("%d", listingId), listing)
	}

	// Route funds from the realm's own account (holding the exact ugnot just received).
	sellerProceeds := cost - fee
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	realmAddr := unsafe.CurrentRealm().Address()
	if fee > 0 {
		bnk.SendCoins(realmAddr, treasury, chain.Coins{chain.NewCoin("ugnot", fee)})
	}
	if sellerProceeds > 0 {
		bnk.SendCoins(realmAddr, listing.Seller, chain.Coins{chain.NewCoin("ugnot", sellerProceeds)})
	}

	// Transfer tokens and measure delta (fee-on-transfer protection)
	buyerBalBefore := tokenfactory_v2.BalanceOf(listing.Symbol, buyer)

	tokenfactory_v2.TransferFrom(cross(cur), listing.Symbol, listing.Seller, buyer, qty)

	buyerBalAfter := tokenfactory_v2.BalanceOf(listing.Symbol, buyer)
	delta := buyerBalAfter - buyerBalBefore
	if delta != qty {
		panic("token transfer delta mismatch (fee-on-transfer not supported)")
	}

	chain.Emit("Filled",
		"id", ufmt.Sprintf("%d", listingId),
		"buyer", string(buyer),
		"seller", string(listing.Seller),
		"symbol", listing.Symbol,
		"qty", ufmt.Sprintf("%d", qty),
		"unitPrice", ufmt.Sprintf("%d", listing.UnitPrice),
		"feeBps", ufmt.Sprintf("%d", feeBps),
		"fee", ufmt.Sprintf("%d", fee),
	)
}

// ── Read Getters ─────────────────────────────────────────────────────────────

// EngineAddress returns this realm's on-chain address — the account sellers approve to
// move their tokens and the settlement account. Exposed so the frontend/deploy ceremony
// can wire the engine without hardcoding the derived address (mirrors nft_market_v3
// MarketAddress()).
func EngineAddress() address {
	return unsafe.CurrentRealm().Address()
}

func GetListing(listingId uint64) *Listing {
	listingRaw, exists := listings.Get(ufmt.Sprintf("%d", listingId))
	if !exists {
		return nil
	}
	return listingRaw.(*Listing)
}

// Note: In production we'd want paginated getters here to prevent O(N) gas limits.
// For v1.1, we'll return all active listings or window them.
func GetListings() []*Listing {
	var result []*Listing
	listings.Iterate("", "", func(key string, value interface{}) bool {
		result = append(result, value.(*Listing))
		return false
	})
	return result
}

// GetListingsCSV returns listings formatted as "ID|Seller|Symbol|UnitPrice|Amount,ID|..."
// to avoid the frontend needing to parse raw Amino struct outputs.
func GetListingsCSV() string {
	out := ""
	listings.Iterate("", "", func(key string, value interface{}) bool {
		l := value.(*Listing)
		row := ufmt.Sprintf("%d|%s|%s|%d|%d", l.Id, string(l.Seller), l.Symbol, l.UnitPrice, l.Amount)
		if out == "" {
			out = row
		} else {
			out += "," + row
		}
		return false
	})
	return out
}
